import heapq

gph = {"S": [("A", 1), ("B", 4)], "A": [("C", 2), ("B", 3)], "B": [("G", 2)], "C": [("G", 1)], "G": []}
h = {"S": 3, "A": 2, "B": 1, "C": 1, "G": 0}
hstar = {"S": 4, "A": 3, "B": 2, "C": 1, "G": 0}

def astar(hh):
    pq = [(hh["S"], 0, "S")]
    best = {"S": 0}
    order = []
    while pq:
        f, g, n = heapq.heappop(pq)
        if g != best.get(n, 10**9):
            continue
        order.append(n)
        if n == "G":
            return order, g
        for m, c in gph[n]:
            ng = g + c
            if ng < best.get(m, 10**9):
                best[m] = ng
                heapq.heappush(pq, (ng + hh[m], ng, m))

def greedy(hh):
    pq = [(hh["S"], 0, "S")]
    seen = set()
    order = []
    while pq:
        hv, g, n = heapq.heappop(pq)
        if n in seen:
            continue
        seen.add(n)
        order.append(n)
        if n == "G":
            return order, g
        for m, c in gph[n]:
            heapq.heappush(pq, (hh[m], g + c, m))

for n, nbrs in gph.items():
    assert h[n] <= hstar[n]
    for m, c in nbrs:
        assert h[n] <= c + h[m]
order, cost = astar(h)
assert order == ["S", "A", "C", "G"] and cost == 4
go, gc = greedy(h)
assert go == ["S", "B", "G"] and gc == 6
hbad = dict(h)
hbad["C"] = 5
assert hbad["C"] > hstar["C"]
border, bcost = astar(hbad)
assert border == ["S", "A", "B", "G"] and bcost == 6
# second graph: optimal cost is min(4+5, 6+4, 3+8)
assert min(4 + 5, 6 + 4, 3 + 8) == 9
print(order, cost, gc, bcost)
